from ta_emss.utilities.trs.commands.emssim import EmssimCommand


class Env(EmssimCommand):
    def __init__(self, method="env", timeout=60, rpc_connection_name='localRPC'):
        super(Env, self).__init__(method, timeout, rpc_connection_name)
        self.params = None

    def on_new_data(self, **data):
        data = super(Env, self).on_new_data(**data)
        if "msg" in data:
            if (data["msg"] == "environmental data"):
                self._ret['env'] = data["env"]
        elif ("status" in data):
            self._ret["status"] = data["status"]
